14	/// Complete the given command, shell-agnostic
15	pub fn complete(
16	    cmd: &mut clap::Command,
17	    args: Vec<OsString>,
18	    arg_index: usize,
19	    current_dir: Option<&std::path::Path>,
20	) -> Result<Vec<CompletionCandidate>, std::io::Error> {
21	    debug!("complete: args={args:?}, arg_index={arg_index:?}, current_dir={current_dir:?}");
22	    cmd.build();
23	
24	    let mut raw_args = clap_lex::RawArgs::new(args);
25	    let mut cursor = raw_args.cursor();
26	    let mut target_cursor = raw_args.cursor();
27	    raw_args.seek(
28	        &mut target_cursor,
29	        clap_lex::SeekFrom::Start(arg_index as u64),
30	    );
31	    // As we loop, `cursor` will always be pointing to the next item
32	    raw_args.next_os(&mut target_cursor);
33	    debug!("complete: target_cursor={target_cursor:?}");
34	
35	    // TODO: Multicall support
36	    if !cmd.is_no_binary_name_set() {
37	        raw_args.next_os(&mut cursor);
38	    }
39	
40	    let mut current_cmd = &*cmd;
41	    let mut pos_index = 1;
42	    let mut is_escaped = false;
43	    let mut next_state = ParseState::ValueDone;
44	    let mut used_args = Vec::<clap::Id>::new();
45	    while let Some(arg) = raw_args.next(&mut cursor) {
46	        let current_state = next_state;
47	        next_state = ParseState::ValueDone;
48	        debug!(
49	            "complete::next: arg={:?}, current_state={current_state:?}, cursor={cursor:?}",
50	            arg.to_value_os(),
51	        );
52	        if let ParseState::Opt((opt, _)) = &current_state {
53	            // A value terminator ends a multi-value option regardless of the
54	            // word's shape: unlike a flag-like word, it never starts a new
55	            // argument, and unlike any other word, it is never one of the
56	            // option's values. A flag-shaped terminator only wins over flag
57	            // parsing when the option accepts hyphen values, matching the
58	            // parser's precedence.
59	            if is_value_terminator(opt, &arg)
60	                && (opt.is_allow_hyphen_values_set() || !is_flag_like(&arg))
61	            {
62	                if cursor == target_cursor {
63	                    // The cursor sits on the terminator itself. Complete as if
64	                    // it had already been submitted and an empty word followed,
65	                    // so ordinary completion resumes and the terminator is not
66	                    // offered as a candidate.
67	                    raw_args.insert(&target_cursor, [OsString::new()]);
68	                    let mut word_cursor = target_cursor;
69	                    let word = raw_args
70	                        .next(&mut word_cursor)
71	                        .expect("an empty word was just inserted");
72	                    return complete_arg(
73	                        &word,
74	                        current_cmd,
75	                        current_dir,
76	                        pos_index,
77	                        is_escaped,
78	                        ParseState::ValueDone,
79	                        &used_args,
80	                    );
81	                }
82	                next_state = ParseState::ValueDone;
83	                continue;
84	            }
85	        }
86	        if cursor == target_cursor {
87	            return complete_arg(
88	                &arg,
89	                current_cmd,
90	                current_dir,
91	                pos_index,
92	                is_escaped,
93	                current_state,
94	                &used_args,
95	            );
96	        }
97	
98	        if !is_escaped && !matches!(current_state, ParseState::Opt(..) | ParseState::Pos(..)) {
99	            if let Ok(value) = arg.to_value() {
100	                if let Some(next_cmd) = current_cmd.find_subcommand(value) {
101	                    current_cmd = next_cmd;
102	                    pos_index = 1;
103	                    used_args.clear();
104	                    continue;
105	                }
106	            }
107	        }
108	
109	        if is_escaped {
110	            (next_state, pos_index) =
111	                parse_positional(current_cmd, pos_index, is_escaped, current_state);
112	        } else if arg.is_escape() {
113	            is_escaped = true;
114	            // Like the parser, `--` jumps straight to a `last(true)`
115	            // positional, skipping any unfilled positionals.
116	            if let Some(last_index) = current_cmd
117	                .get_positionals()
118	                .filter(|p| p.is_last_set())
119	                .filter_map(|p| p.get_index())
120	                .max()
121	            {
122	                pos_index = last_index;
123	            }
124	        } else if opt_allows_hyphen(&current_state, &arg) {
125	            match current_state {
126	                ParseState::Opt((opt, count)) => next_state = parse_opt_value(opt, count),
127	                _ => unreachable!("else branch is only reachable in Opt state"),
128	            }
129	        } else if let Some((flag, value)) = arg.to_long() {
130	            if let Ok(flag) = flag {
131	                let opt = current_cmd.get_arguments().find(|a| is_long_match(a, flag));
132	
133	                if let Some(opt) = opt {
134	                    record_used_arg(&mut used_args, opt.get_id());
135	                    if opt.get_num_args().expect("built").takes_values() {
136	                        // An attached value (`--opt=value`) counts toward the
137	                        // option's values just like a space-separated one, so
138	                        // that completing after `--opt=value` sees the same
139	                        // state as completing after `--opt value`.
140	                        // An empty attached value (`--opt=`) types no value
141	                        // yet, so the option stays pending.
142	                        let count = value
143	                            .filter(|v| !v.is_empty())
144	                            .map(|v| attached_value_count(opt, v))
145	                            .unwrap_or(0);
146	                        next_state = parse_opt_value(opt, count);
147	                    };
148	                } else if pos_allows_hyphen(current_cmd, pos_index) {
149	                    (next_state, pos_index) =
150	                        parse_positional(current_cmd, pos_index, is_escaped, current_state);
151	                }
152	            }
153	        } else if let Some(short) = arg.to_short() {
154	            let (_, matched_opts, takes_value_opt, mut short) =
155	                parse_shortflags(current_cmd, short);
156	            for opt in &matched_opts {
157	                record_used_arg(&mut used_args, opt.get_id());
158	            }
159	            if let Some(opt) = takes_value_opt {
160	                // An attached value (`-ovalue`, `-o=value`) counts toward the
161	                // option's values just like a space-separated one. An empty
162	                // attached value (`-o=`) types no value yet, so the option
163	                // stays pending instead of being treated as satisfied.
164	                let count = short
165	                    .next_value_os()
166	                    .map(|v| v.strip_prefix("=").unwrap_or(v))
167	                    .filter(|v| !v.is_empty())
168	                    .map(|v| attached_value_count(opt, v))
169	                    .unwrap_or(0);
170	                next_state = parse_opt_value(opt, count);
171	            } else if pos_allows_hyphen(current_cmd, pos_index) {
172	                (next_state, pos_index) =
173	                    parse_positional(current_cmd, pos_index, is_escaped, current_state);
174	            }
175	        } else {
176	            match current_state {
177	                ParseState::ValueDone | ParseState::Pos(..) => {
178	                    (next_state, pos_index) =
179	                        parse_positional(current_cmd, pos_index, is_escaped, current_state);
180	                }
181	                ParseState::Opt((opt, count)) => next_state = parse_opt_value(opt, count),
182	            }
183	        }
184	    }
185	
186	    Err(std::io::Error::other("no completion generated"))
187	}
