304	fn complete_option(
305	    arg: &clap_lex::ParsedArg<'_>,
306	    cmd: &clap::Command,
307	    current_dir: Option<&std::path::Path>,
308	) -> Vec<CompletionCandidate> {
309	    debug!("complete_option: arg={arg:?}, current_dir={current_dir:?}");
310	    let mut completions = Vec::<CompletionCandidate>::new();
311	    if arg.is_empty() {
312	        completions.extend(longs_and_visible_aliases(cmd));
313	        completions.extend(hidden_longs_aliases(cmd));
314	
315	        let dash_or_arg = if arg.is_empty() {
316	            "-".into()
317	        } else {
318	            arg.to_value_os().to_string_lossy()
319	        };
320	        completions.extend(
321	            shorts_and_visible_aliases(cmd)
322	                .into_iter()
323	                .map(|comp| comp.add_prefix(dash_or_arg.to_string())),
324	        );
325	    } else if arg.is_stdio() {
326	        // HACK: Assuming knowledge of is_stdio
327	        let dash_or_arg = if arg.is_empty() {
328	            "-".into()
329	        } else {
330	            arg.to_value_os().to_string_lossy()
331	        };
332	        completions.extend(
333	            shorts_and_visible_aliases(cmd)
334	                .into_iter()
335	                .map(|comp| comp.add_prefix(dash_or_arg.to_string())),
336	        );
337	
338	        completions.extend(longs_and_visible_aliases(cmd));
339	        completions.extend(hidden_longs_aliases(cmd));
340	    } else if arg.is_escape() {
341	        // HACK: Assuming knowledge of is_escape
342	        completions.extend(longs_and_visible_aliases(cmd));
343	        completions.extend(hidden_longs_aliases(cmd));
344	    } else if let Some((flag, value)) = arg.to_long() {
345	        if let Ok(flag) = flag {
346	            if let Some(value) = value {
347	                if let Some(arg) = cmd.get_arguments().find(|a| is_long_match(a, flag)) {
348	                    completions.extend(
349	                        complete_arg_value(value.to_str().ok_or(value), arg, current_dir, 0)
350	                            .into_iter()
351	                            .map(|comp| comp.add_prefix(format!("--{flag}="))),
352	                    );
353	                }
354	            } else {
355	                completions.extend(
356	                    longs_and_visible_aliases(cmd)
357	                        .into_iter()
358	                        .filter(|comp| comp.get_value().starts_with(format!("--{flag}").as_str())),
359	                );
360	                completions.extend(
361	                    hidden_longs_aliases(cmd)
362	                        .into_iter()
363	                        .filter(|comp| comp.get_value().starts_with(format!("--{flag}").as_str())),
364	                );
365	            }
366	        }
367	    } else if let Some(short) = arg.to_short() {
368	        if !short.is_negative_number() {
369	            // Find the first takes_values option.
370	            let (leading_flags, _, takes_value_opt, mut short) = parse_shortflags(cmd, short);
371	
372	            // Clone `short` to `peek_short` to peek whether the next flag is a `=`.
373	            if let Some(opt) = takes_value_opt {
374	                let mut peek_short = short.clone();
375	                let has_equal = if let Some(Ok('=')) = peek_short.next_flag() {
376	                    short.next_flag();
377	                    true
378	                } else {
379	                    false
380	                };
381	
382	                let value = short.next_value_os().unwrap_or(OsStr::new(""));
383	                completions.extend(
384	                    complete_arg_value(value.to_str().ok_or(value), opt, current_dir, 0)
385	                        .into_iter()
386	                        .map(|comp| {
387	                            let sep = if has_equal { "=" } else { "" };
388	                            comp.add_prefix(format!("-{leading_flags}{sep}"))
389	                        }),
390	                );
391	            } else {
392	                completions.extend(
393	                    shorts_and_visible_aliases(cmd)
394	                        .into_iter()
395	                        .map(|comp| comp.add_prefix(format!("-{leading_flags}"))),
396	                );
397	            }
398	        }
399	    }
400	    debug!("complete_option: completions={completions:?}");
401	    completions
402	}
