503	fn complete_value_candidates(
504	    value: &OsStr,
505	    completer: &dyn ValueCandidates,
506	) -> Vec<CompletionCandidate> {
507	    debug!("complete_value_candidates: value={value:?}");
508	
509	    let mut values = completer.candidates();
510	    values.retain(|comp| comp.get_value().starts_with(&value.to_string_lossy()));
511	    values
512	}
513	
514	fn complete_candidates_str(
515	    value: &str,
516	    mut values: Vec<CompletionCandidate>,
517	) -> Vec<CompletionCandidate> {
518	    debug!("complete_candidates_str: value={value:?}");
519	
520	    values.retain(|comp| comp.get_value().starts_with(value));
521	    values
522	}
523	
524	fn complete_value_candidates_str(
525	    value: &str,
526	    completer: &dyn ValueCandidates,
527	) -> Vec<CompletionCandidate> {
528	    debug!("complete_value_candidates_str: value={value:?}");
529	
530	    complete_candidates_str(value, completer.candidates())
531	}
