533	fn complete_subcommand(value: &str, cmd: &clap::Command) -> Vec<CompletionCandidate> {
534	    debug!(
535	        "complete_subcommand: cmd={:?}, value={:?}",
536	        cmd.get_name(),
537	        value
538	    );
539	
540	    let mut scs: Vec<CompletionCandidate> = subcommands(cmd)
541	        .into_iter()
542	        .filter(|x| x.get_value().starts_with(value))
543	        .collect();
544	    if cmd.is_allow_external_subcommands_set() {
545	        let external_completer = cmd.get::<SubcommandCandidates>();
546	        if let Some(completer) = external_completer {
547	            scs.extend(complete_value_candidates_str(
548	                value,
549	                completer.value_candidates(),
550	            ));
551	        }
552	    }
553	
554	    scs.dedup();
555	    scs
556	}
