    /// levels mid-group.
    ///
    /// `used` holds the canonical names of every already committed segment;
    /// `valid` is `false` once a committed segment failed validation (empty,
    /// unknown, or repeated).
    DelimOpt {
        opt: &'a clap::Arg,
        used: Vec<String>,
        valid: bool,
    },
}

