use clap::Command;
use std::ffi::OsString;
fn build() -> Command {
    Command::new("tool")
        .disable_help_flag(true).disable_version_flag(true).disable_help_subcommand(true)
        .arg(clap::Arg::new("tag").long("tag")
            .value_parser(["red","green","blue"]).value_delimiter(',')
            .action(clap::ArgAction::Append))
        .arg(clap::Arg::new("src").value_parser(["src","dst"]))
        .subcommand(Command::new("run").disable_help_flag(true).disable_version_flag(true).disable_help_subcommand(true))
}
fn vals(ws:&[&str]) -> String {
    let mut cmd=build();
    let a:Vec<OsString>=ws.iter().map(OsString::from).collect(); let n=a.len();
    clap_complete::engine::complete(&mut cmd,a,n-1,None).unwrap()
      .iter().map(|c|c.get_value().to_string_lossy().into_owned()).collect::<Vec<_>>().join(", ")
}
fn main(){
    println!("a [{}]", vals(&["tool","--tag","red,green","--tag","blue,"]));
    println!("b [{}]", vals(&["tool","--tag","red,green","--tag","blue",""]));
    println!("c [{}]", vals(&["tool","--tag","red","--tag","green,","b"]));
    println!("d [{}]", vals(&["tool","--tag","red","--tag","red,"]));
    println!("e [{}]", vals(&["tool","--tag","red","--tag","red,green"]));
}
EOF
